## Why This Is Asked
This question tests advanced JavaScript patterns including closures, per-key caching, in-flight deduplication, concurrency control, TTL semantics, and dynamic import boundaries.

## Key Concepts
- **Closures**: Hide internal state from outside access
- **Per-key caching with TTL**: Store module exports with expiration timestamps
- **In-flight deduplication**: Return the same Promise for concurrent requests to the same module
- **Semaphore-like concurrency cap**: Limit simultaneous imports using a counter
- **Background refresh**: Refresh expired modules without blocking subsequent requests

## Code Example
```javascript
function createModuleCache(moduleMap, { ttlMs = 120000, maxInFlight = 3 } = {}) {
  const inFlight = new Map(); // moduleName -> Promise
  const cache = new Map(); // moduleName -> { value, expiry }
  let currentInFlight = 0;

  const acquire = () => new Promise(resolve => {
    const tryAcquire = () => {
      if (currentInFlight < maxInFlight) {
        currentInFlight++;
        resolve();
      } else {
        setTimeout(tryAcquire, 10);
      }
    };
    tryAcquire();
  });

  const release = () => { currentInFlight--; };

  async function load(moduleName) {
    const cached = cache.get(moduleName);
    const isExpired = !cached || Date.now() > cached.expiry;

    if (cached && !isExpired) {
      if (isExpired) {
        load(moduleName).catch(() => {}); // background refresh
      }
      return cached.value;
    }

    if (inFlight.has(moduleName)) {
      return inFlight.get(moduleName);
    }

    const promise = (async () => {
      await acquire();
      try {
        const module = await dynamicImport(moduleMap[moduleName]);
        cache.set(moduleName, {
          value: module,
          expiry: Date.now() + ttlMs
        });
        return module;
      } finally {
        release();
        inFlight.delete(moduleName);
      }
    })();

    inFlight.set(moduleName, promise);
    return promise;
  }

  function invalidate(moduleName) {
    cache.delete(moduleName);
  }

  return { load, invalidate };
}
```

## Why This Is Asked
This question evaluates advanced JavaScript patterns including per-key caching, Promise deduplication, TTL-based eviction, and reactive update patterns commonly needed in frontend applications.

## Key Concepts
- **Closures and per-key maps**: Isolated state management for each cached key
- **Promise deduplication**: Avoiding redundant network requests for concurrent loads of the same key
- **TTL-based eviction**: Time-to-live expiration for cache entries
- **Change notifications**: Listener pattern for broadcasting data updates
- **Error handling**: Graceful handling of fetch failures and cache misses

## Code Example
```javascript
function createDataLoader(fetchFn, ttlMs) {
  const cache = new Map();

  function getEntry(key) {
    if (!cache.has(key)) {
      cache.set(key, { promise: null, data: null, expiry: 0, listeners: [] });
    }
    return cache.get(key);
  }

  const notify = (key, data, error) => {
    const entry = cache.get(key);
    if (entry?.listeners.length) {
      entry.listeners.forEach(cb => cb(data, error));
    }
  };

  return {
    load(key) {
      const entry = getEntry(key);
      const now = Date.now();

      if (entry.data && entry.expiry > now) {
        return Promise.resolve(entry.data);
      }

      if (entry.promise) {
        return entry.promise;
      }

      entry.promise = fetchFn(key)
        .then(data => {
          entry.data = data;
          entry.expiry = now + ttlMs;
          entry.promise = null;
          notify(key, data, null);
          return data;
        })
        .catch(err => {
          entry.promise = null;
          notify(key, null, err);
          throw err;
        });

      return entry.promise;
    },

    invalidate(key) {
      const entry = cache.get(key);
      if (entry) {
        entry.data = null;
        entry.expiry = 0;
        entry.promise = null;
      }
    },

    onChange(key, cb) {
      const entry = getEntry(key);
      entry.listeners.push(cb);
      return () => {
        entry.listeners = entry.listeners.filter(l => l !== cb);
      };
    }
  };
}
```

## Usage Example
```javascript
const loader = createDataLoader(fetchUser, 5000);

// Two different keys
loader.onChange('user:1', (data) => console.log('User 1 updated:', data));
loader.onChange('user:2', (data) => console.log('User 2 updated:', data));

// Concurrent loads for same key are deduplicated
loader.load('user:1').then(console.log);
loader.load('user:1').then(console.log); // Reuses in-flight request

// Invalidate and reload
loader.invalidate('user:1');
loader.load('user:1');
```

## Eviction Strategies
- **TTL-based**: Automatic expiration after ttlMs (implemented above)
- **LRU**: Evict least recently used entries when cache size exceeds limit
- **Manual**: Explicit invalidate() calls

## Error Handling
- Failed fetches propagate errors to all waiters via rejected Promise
- Listeners receive error state for reactive UI updates
- In-flight promises are cleared on error to allow retries

